-- Reverse of the up: the same pairs swapped.

BEGIN;

CREATE TEMP TABLE IF NOT EXISTS ocdid_renames (old_id text PRIMARY KEY, new_id text UNIQUE) ON COMMIT DROP;


DELETE FROM ocdid_renames r
WHERE NOT EXISTS (SELECT 1 FROM jurisdictions j WHERE j.jurisdiction_ocdid = r.old_id);

-- An earlier naming pass can have left an inactive shell under a new id: no data, only the
-- organization row every jurisdiction gets. Those go; anything else under a new id aborts below.
CREATE TEMP TABLE IF NOT EXISTS ocdid_shells ON COMMIT DROP AS
SELECT j.jurisdiction_ocdid
  FROM jurisdictions j
  JOIN ocdid_renames r ON r.new_id = j.jurisdiction_ocdid
 WHERE j.status = 'inactive'
   AND NOT EXISTS (SELECT 1 FROM source_records t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM people t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM posts t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM divisions t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM changesets t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM pipeline_runs t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM activity t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid)
   AND NOT EXISTS (SELECT 1 FROM review_session_entries t WHERE t.jurisdiction_ocdid = j.jurisdiction_ocdid);

DELETE FROM organizations o USING ocdid_shells s WHERE o.jurisdiction_ocdid = s.jurisdiction_ocdid;
DELETE FROM jurisdictions j USING ocdid_shells s WHERE j.jurisdiction_ocdid = s.jurisdiction_ocdid;

DO $$
DECLARE
    collisions text;
BEGIN
    SELECT string_agg(r.new_id, ', ') INTO collisions
    FROM ocdid_renames r
    JOIN jurisdictions j ON j.jurisdiction_ocdid = r.new_id;
    IF collisions IS NOT NULL THEN
        RAISE EXCEPTION 'ocdid rename: new id already exists beside its old id: %', collisions;
    END IF;
END $$;

SELECT r.new_id, j.state, j.updated_at, j.data || jsonb_build_object('id', r.new_id),
       j.status, j.level, j.search_text, j.meta_parent_ocdids
FROM jurisdictions j
JOIN ocdid_renames r ON r.old_id = j.jurisdiction_ocdid;

UPDATE divisions d
   SET ocdid = p.new_prefix || substr(d.ocdid, length(p.old_prefix) + 1)
  FROM ocdid_renames r
 CROSS JOIN LATERAL (
     SELECT replace(regexp_replace(r.old_id, '/[^/]+$', ''), 'ocd-jurisdiction', 'ocd-division') AS old_prefix,
            replace(regexp_replace(r.new_id, '/[^/]+$', ''), 'ocd-jurisdiction', 'ocd-division') AS new_prefix
 ) p
 WHERE d.jurisdiction_ocdid = r.old_id
   AND (d.ocdid = p.old_prefix OR d.ocdid LIKE p.old_prefix || '/%');

UPDATE divisions t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE organizations t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE posts t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE source_records t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE changesets t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE people t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE pipeline_runs t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE activity t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;
UPDATE review_session_entries t SET jurisdiction_ocdid = r.new_id FROM ocdid_renames r WHERE t.jurisdiction_ocdid = r.old_id;

UPDATE jurisdictions j
   SET meta_parent_ocdids = (
       SELECT array_agg(COALESCE(r.new_id, p.ocdid) ORDER BY p.ordinality)
         FROM unnest(j.meta_parent_ocdids) WITH ORDINALITY AS p(ocdid, ordinality)
         LEFT JOIN ocdid_renames r ON r.old_id = p.ocdid
   )
 WHERE j.meta_parent_ocdids && (SELECT coalesce(array_agg(old_id), '{}') FROM ocdid_renames);

DELETE FROM jurisdictions j USING ocdid_renames r WHERE j.jurisdiction_ocdid = r.old_id;

COMMIT;
